def change_email():
    # Check if the user is logged in and get their information from the session
    if 'user' not in session:
        return render_template('error.html', message='You must be logged in to change your email')
    user = users[session['user']]

    # Get the new email address and password from the request data
    new_email = request.form['new_email']
    password = request.form['password']

