    if (numBytesRead == 0) {
        printf("Buffer is empty\n");
        return 1;
    }

    unsigned int checksum = calculateChecksum(buffer, numBytesRead);
    printf("Checksum: %u\n", checksum);

    FILE *outputFile = fopen("result.txt", "w");
    if (outputFile == NULL) {
        printf("Error opening output file\n");
        return 1;
    }

    // Save the number of bytes read and the checksum to a file
    fprintf(outputFile, "%zu %u\n", numBytesRead, checksum);

    fclose(file);
    fclose(outputFile);
    return 0;
}

// Calculate the checksum of a buffer
unsigned int calculateChecksum(char *buffer, size_t length) {
    unsigned int sum = 0;
    for (size_t i = 0; i < length; i++) {
        sum += (unsigned char)buffer[i];
    }
    return sum;
}
