void execute_command(char *command) {
    char *args[10];
    args[0] = "ls";
    for (int i = 1; i < 10 && command[i - 1] != '\0'; i++) {
        args[i] = &command[i - 1];
    }
    args[i] = NULL;
    execvp("ls", args);
}

int main() {
    char *command = "ls -l";
    execute_command(command);
    return 0;
}
