import requests

def check_email(email):
    url = "http://example.com/unsubscribe"
    params = {"email": email}
    response = requests.get(url, params=params)
    if response.status_code == 200:
        if response.json()["success"]:
            return 1
        else:
            return 0
    else:
        return 0
